/// <summary>
/// PricingAttribute of table <c>RetailLoyaltyCard</c> field CardNumber.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailLoyaltyCardCardNumber extends UPSPricingAttributeRetailLoyaltyCard implements UPSIPricingAttribute
{
}

