public str getName()
{
    return fieldPName(RetailLoyaltyCard, CardNumber);
}

public Set getAllowedValues()
{
    RetailLoyaltyCard   retailLoyaltyCard;
    var                 ret = new Set(Types::String);

    while select CardNumber from retailLoyaltyCard
    {
        ret.add(retailLoyaltyCard.CardNumber);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, CardNumber));
    qbr.value(queryValue(_value));
}
